//! Pure economy rules. Integer math mirrored 1:1 from packages/sim/src/pricing.ts and council.ts.
//! Parity is enforced by `tests/vectors.json` (generated by `pnpm --filter @lowsec/sim vectors`).
use near_sdk::near;

pub const BPS: i128 = 10_000;
pub const GOODS: [&str; 3] = ["ore", "parts", "fuel"];
pub const TOWNS: [&str; 3] = ["mina", "forja", "puerto"];
pub const GOLD: &str = "gold";
pub const SAFE: u8 = 0;
pub const LOWSEC: u8 = 1;

#[near(serializers = [borsh, json])]
#[derive(Clone, Debug, PartialEq)]
pub struct Params {
    /// base price per good [ore, parts, fuel]
    pub base_price: [u64; 3],
    pub target_stock: u64,
    pub min_price_bps: u64,
    pub max_price_bps: u64,
    pub npc_spread_bps: u64,
    /// Council-controlled multiplier on every faucet (NPC buy orders + starter grant)
    pub faucet_bps: u64,
    pub home_goal_bps: u64,
    pub away_goal_bps: u64,
    pub reversion_bps: u64,
    pub max_stock_factor: u64,
    /// [safe, lowsec]
    pub travel_ticks: [u64; 2],
    pub toll_gold: [u64; 2],
    pub cargo_cap: u64,
    pub ambush_base_bps: u64,
    pub ambush_per_raid_bps: u64,
    pub ambush_max_bps: u64,
    pub ambush_loss_bps: u64,
    pub raider_loot_bps: u64,
    pub raid_min_stake: u64,
    pub raid_fee_bps: u64,
    pub raid_ttl_ticks: u64,
    pub new_player_grant: u64,
    pub epoch_ticks: u64,
    pub council_target_inflation_bps: i64,
    pub council_gain: i64,
    pub council_max_step_bps: u64,
    pub council_min_faucet_bps: u64,
    pub council_max_faucet_bps: u64,
    /// real seconds per game tick (1 game hour) on-chain
    pub tick_seconds: u64,
}

impl Default for Params {
    fn default() -> Self {
        Self {
            base_price: [10, 20, 14],
            target_stock: 400,
            min_price_bps: 2_500,
            max_price_bps: 40_000,
            npc_spread_bps: 9_000,
            faucet_bps: 10_000,
            home_goal_bps: 20_000,
            away_goal_bps: 5_000,
            reversion_bps: 600,
            max_stock_factor: 4,
            travel_ticks: [3, 1],
            toll_gold: [12, 3],
            cargo_cap: 25,
            ambush_base_bps: 800,
            ambush_per_raid_bps: 1_200,
            ambush_max_bps: 6_000,
            ambush_loss_bps: 5_000,
            raider_loot_bps: 2_000,
            raid_min_stake: 100,
            raid_fee_bps: 1_000,
            raid_ttl_ticks: 24,
            new_player_grant: 500,
            epoch_ticks: 24,
            council_target_inflation_bps: 100,
            council_gain: 2,
            council_max_step_bps: 1_000,
            council_min_faucet_bps: 7_000,
            council_max_faucet_bps: 11_000,
            tick_seconds: 10,
        }
    }
}

pub fn ask_price(p: &Params, good: usize, stock: i64) -> u128 {
    let base = p.base_price[good] as i128;
    let s = stock.max(1) as i128;
    let raw = base * p.target_stock as i128 / s;
    let lo = (base * p.min_price_bps as i128 / BPS).max(1);
    let hi = base * p.max_price_bps as i128 / BPS;
    raw.max(lo).min(hi) as u128
}

pub fn bid_price(p: &Params, good: usize, stock: i64, faucet_bps: u64) -> u128 {
    ask_price(p, good, stock) * p.npc_spread_bps as u128 * faucet_bps as u128 / 100_000_000
}

pub fn buy_cost(p: &Params, good: usize, stock: i64, q: u64) -> u128 {
    q as u128 * ask_price(p, good, stock - (q / 2) as i64)
}

pub fn sell_payout(p: &Params, good: usize, stock: i64, q: u64, faucet_bps: u64) -> u128 {
    q as u128 * bid_price(p, good, stock + (q / 2) as i64, faucet_bps)
}

pub fn ambush_chance_bps(p: &Params, route: u8, active_raids: u64) -> u64 {
    if route == SAFE {
        return 0;
    }
    (p.ambush_base_bps + p.ambush_per_raid_bps * active_raids).min(p.ambush_max_bps)
}

/// (burned, looted, kept)
pub fn ambush_split(p: &Params, q: u64, has_raider: bool) -> (u64, u64, u64) {
    let lost = q * p.ambush_loss_bps / 10_000;
    let looted = if has_raider { (q * p.raider_loot_bps / 10_000).min(lost) } else { 0 };
    (lost - looted, looted, q - lost)
}

pub fn raid_fee(p: &Params, stake: u128) -> u128 {
    stake * p.raid_fee_bps as u128 / 10_000
}

pub fn goal_stock(p: &Params, is_home: bool) -> i64 {
    (p.target_stock * if is_home { p.home_goal_bps } else { p.away_goal_bps } / 10_000) as i64
}

pub fn revert_stock(p: &Params, stock: i64, goal: i64) -> i64 {
    if stock == goal {
        return stock;
    }
    let mut d = (goal - stock) * p.reversion_bps as i64 / 10_000;
    if d == 0 {
        d = if goal > stock { 1 } else { -1 };
    }
    (stock + d).max(1).min((p.target_stock * p.max_stock_factor) as i64)
}

pub fn inflation_bps(supply_start: u128, supply_end: u128) -> i64 {
    if supply_start == 0 {
        return 0;
    }
    ((supply_end as i128 - supply_start as i128) * BPS / supply_start as i128) as i64
}

/// The Council's public one-line rule:
/// faucet_next = clamp(faucet * (1 - gain * (inflation - target)), ±max_step, [min, max])
pub fn council_rule(p: &Params, faucet_bps: u64, infl_bps: i64) -> u64 {
    let err = infl_bps - p.council_target_inflation_bps;
    let max = p.council_max_step_bps as i64;
    let step = (-(err * p.council_gain)).max(-max).min(max);
    let next = (faucet_bps as i128 * (BPS + step as i128) / BPS) as u64;
    next.max(p.council_min_faucet_bps).min(p.council_max_faucet_bps)
}

/// On-chain bound: |next - prev| <= prev * max_step
pub fn within_bound(prev: u64, next: u64, max_step_bps: u64) -> bool {
    (next as i128 - prev as i128).unsigned_abs() * 10_000 <= prev as u128 * max_step_bps as u128
}

/// Lane between two towns: 0 mina-forja, 1 forja-puerto, 2 mina-puerto
pub fn lane_index(a: u8, b: u8) -> u8 {
    match (a.min(b), a.max(b)) {
        (0, 1) => 0,
        (1, 2) => 1,
        (0, 2) => 2,
        _ => near_sdk::env::panic_str("invalid lane"),
    }
}

pub fn good_index(token_id: &str) -> Option<usize> {
    GOODS.iter().position(|g| *g == token_id)
}

pub fn town_index(name: &str) -> Option<u8> {
    TOWNS.iter().position(|t| *t == name).map(|i| i as u8)
}
